def find(names, dirs):
    for d in dirs:
        for n in names:
            p = os.path.join(d, n) if d else n
            if os.path.isfile(p): return p
    return None
if not os.path.isdir("routes") or not os.path.isfile("app.py"):
    print("Run this from the project folder (~/W), where app.py is."); sys.exit(1)
tdir = "templates" if os.path.isdir("templates") else ""
eng = find(("engine.py",), ("", "routes"))
base = os.path.dirname(eng) if eng else ""
plan = [(os.path.join(base, "citefile.py"), FILES["citefile.py"]),
        (os.path.join("routes", "cite_file_tool.py"), FILES["cite_file_tool.py"]),
        (os.path.join(tdir, "cite_file.html"), FILES["cite_file.html"])]
def write(p, s):
    open(p + ".new", "w", encoding="utf-8").write(s); os.replace(p + ".new", p)
warn = []
for p, s in plan:
    old = open(p, encoding="utf-8").read() if os.path.isfile(p) else None
    if old == s: print("ok   ", p, "(already current)")
    else:
        write(p, s); print("wrote", p)
# register the tool
tp = os.path.join("routes", "tools.py")
if os.path.isfile(tp):
    t = open(tp, encoding="utf-8").read()
    if "routes.cite_file_tool" in t: print("ok   ", tp, "(already registered)")
    else:
        m = re.search(r"TOOL_MODULES\s*=\s*\(([^)]*)\)", t)
        if not m: warn.append("Could not find TOOL_MODULES in routes/tools.py. Add \"routes.cite_file_tool\" to it by hand.")
        else:
            inner = m.group(1).rstrip()
            if inner.endswith(","): inner = inner[:-1]
            t = t[:m.start(1)] + inner + ', "routes.cite_file_tool"' + t[m.end(1):]
            write(tp, t); print("wrote", tp, "(registered Cite My File)")
else: warn.append("routes/tools.py not found.")
# pypdf
rp = "requirements.txt"
if os.path.isfile(rp):
    r = open(rp, encoding="utf-8").read()
    if re.search(r"(?im)^\s*pypdf\b", r): print("ok   ", rp, "(pypdf already listed)")
    else:
        write(rp, r.rstrip("\n") + "\npypdf\n"); print("wrote", rp, "(added pypdf)")
else: warn.append("requirements.txt not found. Add the line  pypdf  to it, or PDF reading will not work on Render.")
# home tile
hp = find(("home.html",), (tdir, ""))
ICON = '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/><path d="M9 13h6M9 17h4"/></svg>'
TILE = ('      <a class="tool" href="/cite-file">\n        <div class="ti">' + ICON + '</div>\n'
        '        <h3>Cite My File</h3><p>Upload a PDF or Word file, get its citations.</p><span class="open">Open</span></a>\n')
if hp:
    h = open(hp, encoding="utf-8").read()
    if 'href="/cite-file"' in h: print("ok   ", hp, "(tile already there)")
    else:
        soon = re.search(r'      <div class="tool soon"[^\n]*\n[^\n]*\n[^\n]*</div>\n', h)
        anchor = '<h3>Topic Ideas</h3><p>Narrow down a research topic.</p><span class="open">Open</span></a>\n'
        if soon: h = h[:soon.start()] + TILE + h[soon.end():]; how = "replaced one Coming soon square"
        elif h.count(anchor) == 1: h = h.replace(anchor, anchor + TILE, 1); how = "added the tile"
        else: h = None
        if h is None: warn.append("Could not place the home tile. The tool still works at /cite-file.")
        else: write(hp, h); print("wrote", hp, "(" + how + ")")
else: warn.append("home.html not found, so no tile was added. The tool works at /cite-file.")
# news
NEW = {"date": "2026-11-19", "tag": "New", "title": "Cite My File",
  "summary": "Upload a PDF or Word file, or paste text, and get its citation in APA, MLA, Chicago and Harvard.",
  "points": ["Works with PDF, DOCX and DOC files up to 12 MB.",
             "Finds the real record by DOI or title (Crossref) when it can, and tells you when it only guessed.",
             "You can fix any detail before the citations are made.",
             "Your file is read in memory and then discarded. It is not stored.",
             "Save adds only the citation details to your saved papers."],
  "link": "/cite-file", "link_text": "Open Cite My File"}
if os.path.isfile("news.json"):
    try:
        items = json.load(open("news.json", encoding="utf-8"))
        if not isinstance(items, list): raise ValueError("not a list")
        if any(isinstance(n, dict) and n.get("title") == NEW["title"] for n in items): print("ok   ", "news.json (already there)")
        else:
            tmp = "news.json.new"; json.dump([NEW] + items, open(tmp, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
            os.replace(tmp, "news.json"); print("wrote news.json")
    except Exception as e: warn.append("news.json could not be updated (%s)." % e)
else: warn.append("news.json not found, so no news entry was added.")
print()
for w in warn: print("WARNING:", w)
print("Done. Next: run  pip install pypdf  here if you test locally, then commit and push so Render rebuilds.")
